import{VERSION,CHECKED,uid,n,sum,money,incomeTypes,lifeTypes,nonlifeTypes,portfolioTypes,factories,fresh,demo,annual,premiumAnnual,active,cashflow,goalResults,retirementResult,protectionResult,taxResult,warnings,decodePlan,incomeBreakdown,portfolioTax,socialAnnual,incomeTax,incomeMonths,bonusParent,spouseEligible,esgxCarry,debtSchedule,retirementScenarios}from'./model.mjs?v=2.5';
