const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={finance:['01','ข้อมูลการเงิน','เริ่มจากรู้จักเงินของคุณ','รายรับ รายจ่าย สินทรัพย์ และหนี้สิน เชื่อมเป็นภาพเดียว'],protection:['02','ความคุ้มครอง','จัดระเบียบทุกความคุ้มครอง','รวบรวมกรมธรรม์ ประเมินภาระเบี้ย และดูช่องว่างที่ต้องทบทวน'],goals:['03','เป้าหมายและพอร์ต','ให้เงินทุกก้อนมีเป้าหมาย','เห็นศักยภาพการออม และจัดสรรพอร์ตที่มีให้แผนชีวิต'],retirement:['04','แผนเกษียณ','ออกแบบชีวิตหลังเกษียณ','รวมเงินเก็บ กองทุน และรายได้หลังเกษียณจากข้อมูลเดิม'],tax:['05','แผนภาษี','วางแผนภาษีอย่างมีข้อมูล','ปีภาษี 2569 • ประมาณการกรณีทั่วไปและตรวจสิทธิที่เชื่อมจากแผน'],report:['06','ภาพรวมและสรุป','แผนการเงินของคุณ','เปลี่ยนข้อมูลทั้งหมดเป็นลำดับสิ่งที่ควรลงมือทำ']};
const months=['ม.ค.','ก.พ.','มี.ค.','เม.ย.','พ.ค.','มิ.ย.','ก.ค.','ส.ค.','ก.ย.','ต.ค.','พ.ย.','ธ.ค.'];
const sourceHTML=`<div class="source-list"><a href="https://www.rd.go.th/fileadmin/user_upload/kormor/newlaw/dc805.pdf" target="_blank" rel="noopener">พ.ร.ฎ.805: Solar Rooftop (ประกาศใช้ 2 มี.ค.2569)</a><a href="https://www.rd.go.th/region/04/saraburi/85/6868.html" target="_blank" rel="noopener">กรมสรรพากร: e-Donation ตั้งแต่ 1 ม.ค.2569</a><a href="https://www.rd.go.th/fileadmin/tax_pdf/pit/2568/Ins91_241268.pdf" target="_blank" rel="noopener">คู่มือกรมสรรพากร: สิทธิสร้างบ้านและงานศิลปะที่มีผลต่อเนื่อง</a><a href="https://www.rd.go.th/68191.html" target="_blank" rel="noopener">กรมสรรพากร: แบบภาษีปี 2569 (ปัจจุบันมีแบบครึ่งปี)</a><a href="https://www.rd.go.th/65908.html" target="_blank" rel="noopener">กรมสรรพากร: ตารางลดหย่อนปี 2568 ใช้อ้างอิงสิทธิพื้นฐาน</a><a href="https://rd.go.th/556.html" target="_blank" rel="noopener">ประเภทเงินได้และการหักค่าใช้จ่าย</a><a href="https://www.rd.go.th/555.html" target="_blank" rel="noopener">วิธีคำนวณภาษีประจำปีและภาษีขั้นต่ำ</a><a href="https://www.rd.go.th/60058.html" target="_blank" rel="noopener">เบี้ยชีวิต สุขภาพ และบำนาญ</a><a href="https://www.sec.or.th/TH/Pages/News_Detail.aspx?SECID=11027" target="_blank" rel="noopener">ก.ล.ต.: Thai ESG ปี 2567–2569</a><a href="https://www.sec.or.th/TH/Pages/News_Detail.aspx?SECID=11848" target="_blank" rel="noopener">ก.ล.ต.: สิทธิทยอยจาก LTF ไป Thai ESGX</a><a href="https://www.sec.or.th/TH/Documents/Thai%20ESGX/QA-LTF-to-Thai%20ESGX-010468.pdf" target="_blank" rel="noopener">ก.ล.ต.: Thai ESGX ซื้อใหม่ปี 2569 ใช้วงเงินร่วม Thai ESG</a><a href="https://www.scbam.com/th/announce/announce-13122024-1" target="_blank" rel="noopener">บลจ.ไทยพาณิชย์: สิทธิซื้อ SSF สิ้นสุดปี 2567</a><a href="https://www.oic.or.th/manual/" target="_blank" rel="noopener">คปภ.: คู่มือประกันภัยสำหรับประชาชน</a></div>`;
const get=path=>path.split('.').reduce((o,k)=>o?.[k],state);
function set(path,value){const keys=path.split('.'),last=keys.pop();let o=state;for(const k of keys)o=o[k];o[last]=value;dirty=true}
function f(path,label,help='',type='number',options=null,extra=''){if(type==='number'&&!options)return numericField(path,label,help,extra);const value=get(path);let control;if(options)control=`<select data-bind="${path}" ${extra}>${Object.entries(options).map(([k,v])=>`<option value="${esc(k)}" ${String(value)===k?'selected':''}>${esc(v)}</option>`).join('')}</select>`;else if(type==='textarea')control=`<textarea data-bind="${path}" maxlength="10000" ${extra}>${esc(value)}</textarea>`;else control=`<input data-bind="${path}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="any"':type==='text'?'maxlength="160"':''} ${extra}>`;return`<label>${label}${control}${help?`<div class="help">${help}</div>`:''}</label>`}
function check(path,label,help=''){return`<label class="check"><input type="checkbox" data-bind="${path}" ${get(path)?'checked':''}><span>${label}${help?`<div class="help">${help}</div>`:''}</span></label>`}
const select=(p,l,opts,h='')=>f(p,l,h,'text',opts);
const plainBox=(title,sub,body,action='')=>`<section class="card"><div class="card-head"><div><h2>${title}</h2>${sub?`<p class="sub">${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const add=(kind,label='เพิ่มรายการ')=>`<button data-add="${kind}">+ ${label}</button>`;
const del=(kind,i)=>`<button class="danger" data-remove="${kind}" data-index="${i}" aria-label="ลบรายการที่ ${i+1}">ลบรายการ</button>`;
const empty=(title,help)=>`<div class="empty"><b>${title}</b>${help}</div>`;
const details=(title,body,open=false)=>`<details ${open?'open':''}><summary>${title}</summary>${body}</details>`;
const entry=(kind,i,body,title='')=>{const r=state[kind][i];return `<details class="entry" open data-entry="${esc(r.id)}"><summary><b data-entry-title="${esc(r.id)}">${esc(title||r.name||'รายการใหม่')} · ${title?esc(r.name)+' · ':''} ${money(r.amount??r.value??r.premium??r.balance??r.target??0)} บาท</b></summary><div class="entry-head">${del(kind,i)}</div>${body}</details>`};
const row=(label,value)=>`<div class="row"><span>${label}</span><b>${value}</b></div>`;
const stat=(label,value,detail='',cls='')=>`<div class="stat"><div class="label">${label}</div><div class="value ${cls}">${value}</div><div class="detail">${detail}</div></div>`;
const progress=(label,value,target)=>`<div class="progress"><div class="progress-head"><span>${label}</span><b>${target>0?money(value/target*100):'—'}%</b></div><div class="track"><span style="width:${target>0?Math.max(0,Math.min(100,value/target*100)):0}%"></span></div><div class="help">${money(value)} / ${money(target)} บาท</div></div>`;
const table=(headers,rows)=>`<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((x,i)=>`<td ${i?'class="num"':''}>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const result=id=>`<div id="${id}" data-result></div>`;
const purposeOptions=()=>({'unallocated':'ยังไม่จัดสรร','retirement':'เพื่อเกษียณ',...Object.fromEntries(state.goals.map(g=>[g.id,g.name]))});
function heading(){return`${state.profile.example?'<div class="callout">ข้อมูลสมมติสำหรับทดลองใช้งาน • เกษียณใช้เดือนละ 50,000 บาทในมูลค่าเงินวันนี้ ไม่ใช่ข้อมูลของคุณ</div>':''}<div class="page-heading"><div><div class="eyebrow">STEP ${pages[page][0]} / YOUR FINANCIAL BLUEPRINT</div><h1>${pages[page][2]}</h1><p class="sub">${pages[page][3]}</p></div><span class="badge">${esc(state.profile.name||'แผนใหม่')}</span></div>`}
function incomeTaxFields(r,i){const p='incomes.'+i,t=incomeTax(state,r),parent=bonusParent(state,r);return `${select(p+'.taxSource','ยอดภาษีที่ใช้',{manual:'ยอดจริง / ประมาณการทั้งปีที่กรอกเอง',estimate:'คำนวณจากรายรับก่อนหักและรายการหัก'})}${t.coveredBy?`<p class="callout">ยอดภาษีโบนัสนี้รวมอยู่ในหนังสือรับรองของ ${esc(parent.name)} แล้ว จึงไม่นำมาบวกซ้ำ</p>`:r.taxSource==='manual'?`<div class="form-grid">${f(p+'.gross','เงินได้ก่อนหักทั้งปี','เฉพาะรายการนี้ หรือรวมโบนัสที่เชื่อมเมื่อเลือกด้านล่าง')}${f(p+'.withheld','ภาษีหัก ณ ที่จ่ายทั้งปี','ใช้ขอบเขตเดียวกับยอดเงินได้')}</div>`:`<p class="help">${r.amountMode==='gross'?'คำนวณจำนวนงวด × ยอดก่อนหัก และจำนวนงวด × ภาษีหัก ณ ที่จ่าย':'ยอดสุทธิใช้ประมาณภาษีไม่ได้ กรุณาเลือกยอดก่อนหักหรือกรอกยอดตามหนังสือรับรอง'}</p>`}${r.frequency==='monthly'&&r.taxType==='1'&&r.taxSource==='manual'?check(p+'.certificateIncludesBonus','ยอดเงินได้และภาษีในหนังสือรับรองรวมโบนัสที่เชื่อมทั้งหมดแล้ว','เลือกเฉพาะเมื่อทั้งสองยอดรวมโบนัส ห้ามกรอกโบนัสซ้ำในแหล่งเงินได้อื่น'):''}<div id="tax-income-${r.id}" data-result></div>`;}
function flowEntry(kind,r,i){const p=kind+'.'+i;const income=kind==='incomes';return entry(kind,i,`<div class="form-grid four">${f(p+'.name','ชื่อรายการ','','text')}${income?select(p+'.amountMode','ยอดที่จะกรอก',{net:'เงินเข้าบัญชีหลังหักแล้ว',gross:'รายรับก่อนหักตามสลิป'}):''}${f(p+'.amount',income?(r.amountMode==='gross'?'รายรับก่อนหัก (บาท)':'เงินสุทธิเข้าบัญชี (บาท)'):'จำนวนเงิน (บาท)',income?'ต่อหนึ่งงวดตามความถี่ที่เลือก':'ไม่รวมเบี้ย หนี้ และเงินออมที่กรอกแยก')}${select(p+'.frequency','ความถี่',{monthly:'ทุกเดือน',yearly:'ครั้งเดียวในปี'})}${r.frequency==='yearly'?select(p+'.month','เดือนที่รับ / จ่าย',Object.fromEntries(months.map((m,i)=>[i+1,m]))):income?select(p+'.startMonth','เดือนเริ่มรับ',Object.fromEntries(months.map((m,i)=>[i+1,m])))+select(p+'.endMonth','เดือนสุดท้ายที่รับ',Object.fromEntries(months.map((m,i)=>[i+1,m]))):''}</div>${income?`${r.salaryId?`<p class="help">โบนัสของ ${esc(bonusParent(state,r)?.name||'เงินเดือนที่ถูกลบ/เปลี่ยนประเภท')} • แยกเดือนรับเงินจริง แต่ภาษีตรวจขอบเขตหนังสือรับรองร่วมกัน</p>`:''}<h3>รายการหักจากรายรับ</h3><p class="help">${r.amountMode==='gross'?'ระบบจะหักรายการด้านล่างเพื่อคำนวณเงินเข้าบัญชี':'ยอดที่กรอกเป็นเงินสุทธิแล้ว รายการด้านล่างใช้บันทึกข้อมูลและเชื่อมภาษี ไม่หัก Cash Flow ซ้ำ'}</p><div class="form-grid">${f(p+'.socialDeduct','ประกันสังคมส่วนของคุณ / งวด','ตามสลิป ไม่รวมส่วนนายจ้าง')}${f(p+'.taxDeduct','ภาษีหัก ณ ที่จ่าย / งวด','ภาษีทั้งปีให้ยืนยันตามหนังสือรับรองด้านล่าง')}${f(p+'.otherDeduct','รายการหักอื่น / งวด','ไม่รวม PVD ประกันสังคม หรือรายจ่ายที่กรอกแล้ว')}</div>${result('income-'+r.id)}<p class="help">เงินสะสม PVD ดึงจากกองทุนที่ผูกกับรายรับนี้ด้านล่าง ไม่ต้องกรอกซ้ำในรายการหักอื่น</p>${details('ข้อมูลเงินได้สำหรับภาษีทั้งปี',`<div class="form-grid">${select(p+'.taxType','ประเภทเงินได้',incomeTypes)}${incomeTaxFields(r,i)}</div>`)}${r.frequency==='monthly'&&r.taxType==='1'?`<button data-add="bonus" data-salary="${i}">+ เพิ่มโบนัส</button><p class="help">โบนัสเชื่อมเงินเดือนนี้โดยตรง เพิ่มได้หลายครั้ง เลือกเดือนรับแต่ละครั้ง และตรวจว่าหนังสือรับรองรวมโบนัสหรือไม่</p>`:''}`:check(p+'.essential','เป็นรายจ่ายจำเป็น ใช้คำนวณเงินสำรอง')}`)}
function pvdSection(){return box('กองทุนสำรองเลี้ยงชีพ (PVD)','กรอกที่นี่ครั้งเดียว เชื่อมสินทรัพย์ พอร์ต แผนเกษียณ และภาษี',state.portfolios.map((r,i)=>r.type==='PVD'?portfolioEntry(r,i):'').join('')||empty('มี PVD จากที่ทำงานหรือไม่?','เพิ่มกองทุนปัจจุบันหรือกองทุนเดิมที่ยังคงเงินไว้ หากไม่มีให้ข้ามได้'),add('pvd','PVD'))}
function socialSection(){return box('ประกันสังคมของเจ้าของแผน','รายการหักผ่านนายจ้างกรอกในรายรับด้านบน ส่วนที่จ่ายเองกรอกที่นี่',`<div class="form-grid">${select('retirement.socialScheme','สถานะประกันสังคม',{'none':'ไม่มี (หากยังไม่ทราบ ให้บันทึกในหมายเหตุ)','33':'มาตรา 33','39':'มาตรา 39','40':'มาตรา 40'})}${f('retirement.socialMonths','ส่งเงินสมทบสะสมแล้ว (เดือน)','อ้างอิงประวัติจริง ไม่คำนวณจากเงินส่งต่อเดือน')}${f('retirement.socialOwnMonthly','เงินสมทบที่จ่ายเองนอกสลิป / เดือน','เช่น ม.39 / ม.40 ระบบหักในรายจ่ายให้ ไม่ต้องกรอกซ้ำ')}</div><div class="form-grid two" style="margin-top:16px">${select('tax.socialAuto','ยอดประกันสังคมสำหรับภาษี',{'true':'ประมาณการยอดปัจจุบันเต็ม 12 เดือน','false':'ใช้ยอดจ่ายจริงทั้งปีตามหลักฐาน'})}${!state.tax.socialAuto?f('tax.socialPaid','เงินสมทบที่จ่ายจริงทั้งปี','รวมทุกมาตราที่จ่ายเองในปีนี้ ไม่รวมเงินสมทบนายจ้าง'):''}</div>${result('social-finance')}<p class="help">ยอดส่งเงินสมทบไม่ใช่ยอดบำนาญ หน้าเกษียณยังต้องกรอกสิทธิคาดการณ์จากประกันสังคม หากเปลี่ยนงานหรือมาตราระหว่างปี ให้ใช้ยอดภาษีตามหลักฐาน</p>`)}
function financePage(){return plainBox('เริ่มวางแผนในแบบของคุณ','เลือกเพื่อแนะนำประเภทเงินได้ใหม่ ข้อมูลเดิมไม่เปลี่ยน',`<div class="form-grid two">${select('profile.occupation','อาชีพหลัก',{employee:'พนักงาน / ข้าราชการ',freelance:'ฟรีแลนซ์ / ตัวแทน',business:'ธุรกิจ',investor:'รายได้ลงทุน / ค่าเช่า'})}${select('profile.focus','เรื่องที่อยากเริ่ม',{finance:'ภาพรวมการเงิน',retirement:'เกษียณ',tax:'ภาษี',protection:'ความคุ้มครอง',goals:'เป้าหมายและพอร์ต'})}</div><button data-page="${esc(state.profile.focus)}">ไปเรื่องที่เลือก</button><p class="help">เริ่มจากรายรับและรายจ่ายเพื่อดูผลเบื้องต้น แล้วเติมรายละเอียดที่เกี่ยวข้องทีหลัง</p>`)+box('ข้อมูลเจ้าของแผน','ใช้ชื่อเล่นได้ ไม่ต้องกรอกเลขบัตรประชาชน',`<div class="form-grid">${f('profile.name','ชื่อแผน / ชื่อลูกค้า','','text')}${f('profile.age','อายุปัจจุบัน (ปี)','','number',null,'max="120"')}${f('profile.asOf','วันที่ประเมิน','','date')}${f('profile.dependents','จำนวนคนที่ดูแล','','number',null,'step="1"')}${select('profile.marital','สถานภาพ',{single:'โสด',married:'สมรส',other:'อื่น ๆ'})}${f('profile.reserveMonths','เป้าหมายเงินสำรอง (เดือน)','ปรับตามความมั่นคงของรายได้')}</div>`)+box('รายรับและรายการหัก','เลือกกรอกยอดก่อนหักหรือยอดสุทธิ ระบบแสดงเงินรับจริงให้ทันที',state.incomes.length?state.incomes.map((r,i)=>flowEntry('incomes',r,i)).join(''):empty('เพิ่มแหล่งรายรับแรก','เงินเดือน ค่านายหน้า ธุรกิจ ค่าเช่า หรือรายรับอื่น'),add('incomes','รายรับ'))+(state.profile.occupation==='employee'?pvdSection()+socialSection():details('PVD และประกันสังคม — เปิดกรอกเมื่อเกี่ยวข้อง',pvdSection()+socialSection()))+box('รายจ่าย','ค่าใช้จ่ายประจำและรายการที่จ่ายเป็นครั้งคราว',state.expenses.length?state.expenses.map((r,i)=>flowEntry('expenses',r,i)).join(''):empty('รายจ่ายที่อยากเห็นชัด','เช่น อาหาร ที่อยู่อาศัย เดินทาง และพักผ่อน'),add('expenses','รายจ่าย'))+box('สินทรัพย์','รวม PVD ด้านบนและพอร์ตหน้า 3 อัตโนมัติ ไม่กรอกเงินก้อนเดิมซ้ำ',state.assets.map((r,i)=>{const p='assets.'+i;return entry('assets',i,`<div class="form-grid four">${f(p+'.name','ชื่อสินทรัพย์','','text')}${select(p+'.kind','ประเภท',{cash:'เงินสด / เงินฝาก',property:'บ้าน / ที่ดิน',vehicle:'รถยนต์',other:'ทรัพย์สินอื่น'})}${f(p+'.value','มูลค่าปัจจุบัน')}${select(p+'.purpose','เงินก้อนนี้ตั้งใจใช้ทำอะไร?',r.kind==='cash'?{'emergency':'เงินสำรองฉุกเฉิน',...purposeOptions()}:{unallocated:'ทรัพย์สิน ไม่ใช่เงินพร้อมใช้'})}</div>`)}).join('')||empty('เพิ่มสินทรัพย์ที่มี','ใช้มูลค่าปัจจุบันโดยประมาณ'),add('assets','สินทรัพย์'))+box('หนี้สิน','ยอดคงเหลือใช้คำนวณฐานะการเงิน ค่างวดใช้ใน Cash Flow',state.debts.map((r,i)=>{const p='debts.'+i;return entry('debts',i,`<div class="form-grid">${f(p+'.name','ประเภทหนี้ / เจ้าหนี้','','text')}${f(p+'.balance','ยอดหนี้คงเหลือ')}${f(p+'.monthly','ค่างวดต่อเดือน')}${f(p+'.rate','ดอกเบี้ย (% ต่อปี)','','number',null,'max="100"')}${select(p+'.method','วิธีประมาณหนี้',{manual:'ใช้ค่างวด/วันจบตามสัญญา (รวมรถแบบ Flat rate)',reducing:'จำลองลดต้นลดดอก อัตราคงที่'})}${r.method==='reducing'?f(p+'.extra','โปะเพิ่มต่อเดือน','สมมติว่าโปะลดเงินต้น ไม่มีค่าปรับ'):''}${f(p+'.end','วันที่คาดว่าจะปิดหนี้','','date')}${f(p+'.homeInterest','ดอกเบี้ยบ้านที่ใช้สิทธิปีนี้','เฉพาะส่วนของคุณที่เข้าเงื่อนไข ตามหนังสือรับรอง')}</div>${result('debt-'+r.id)}`)}).join('')||empty('ไม่มีหนี้ก็ข้ามได้','เพิ่มบ้าน รถ บัตรเครดิต หรือสินเชื่ออื่น'),add('debts','หนี้'))+`<h2 class="result-title">สรุปภาพรวมการเงิน</h2>${result('finance-results')}`}
function policyEntry(r,i){const p='policies.'+i;return entry('policies',i,`<div class="form-grid">${f(p+'.company','บริษัทประกัน','','text')}${f(p+'.name','ชื่อแบบ / แผนประกัน','','text')}${f(p+'.number','เลขกรมธรรม์ (ไม่บังคับ)','','text')}${select(p+'.group','หมวด',{life:'ประกันชีวิต / สัญญาเพิ่มเติม',nonlife:'ประกันวินาศภัย'})}${select(p+'.type','ประเภท',r.group==='life'?lifeTypes:nonlifeTypes)}${select(p+'.status','สถานะ',{active:'มีผลบังคับ',lapsed:'ขาดอายุ / ยกเลิก',matured:'ครบสัญญา'})}${select(p+'.insured','ผู้เอาประกัน',{self:'เจ้าของแผน',spouse:'คู่สมรส',child:'บุตร',other:'บุคคลอื่น'})}${f(p+'.insuredName','ชื่อผู้เอาประกัน / ทรัพย์สิน','','text')}${f(p+'.premium','เบี้ยต่อหนึ่งงวด','รวมสัญญาเพิ่มเติมทั้งหมด ไม่กรอกเบี้ยซ้ำ')}${select(p+'.frequency','รอบชำระ',{yearly:'รายปี',half:'ราย 6 เดือน',quarterly:'ราย 3 เดือน',monthly:'รายเดือน'})}${f(p+'.due','วันครบกำหนดชำระครั้งถัดไป','','date')}${f(p+'.start','วันเริ่มคุ้มครอง','','date')}${f(p+'.end','วันสิ้นสุดความคุ้มครอง','เว้นว่างหากยังไม่ทราบ / ตลอดชีพ','date')}${f(p+'.payEnd','วันสิ้นสุดชำระเบี้ย','','date')}${f(p+'.beneficiary','ผู้รับผลประโยชน์ / สัดส่วน','','text')}</div>${details('วงเงินคุ้มครองและสัญญาเพิ่มเติม',`<div class="form-grid">${f(p+'.death','เสียชีวิตทั่วไป','ทุนปัจจุบัน ไม่รวมอุบัติเหตุซ้ำ')}${f(p+'.accidentDeath','ทุนอุบัติเหตุเพิ่มเติม')}${f(p+'.health','วงเงินสุขภาพตามแผน','ระบุฐานวงเงินในรายละเอียด เช่น ต่อปี / ต่อครั้ง')}${f(p+'.ci','โรคร้ายแรง')}${f(p+'.disability','ทุพพลภาพ')}${f(p+'.property','ทรัพย์สิน / ความรับผิด')}${f(p+'.deductible','ความรับผิดส่วนแรก (บาท)')}${f(p+'.copay','ร่วมจ่าย (%)','','number',null,'max="100"')}${f(p+'.agent','ผู้ติดต่อ / ตัวแทน','','text')}</div><div class="form-grid two" style="margin-top:16px">${f(p+'.riders','รายการสัญญาเพิ่มเติม','ชื่อสัญญา วงเงิน และเบี้ยแต่ละส่วน — รวมเบี้ยไว้ด้านบนแล้ว','textarea')}${f(p+'.details','รายละเอียดผลประโยชน์','ค่าห้อง OPD ต่อปี/ต่อครั้ง ทะเบียนรถ ที่อยู่บ้าน ฯลฯ','textarea')}${f(p+'.exclusions','ข้อยกเว้น / ระยะรอคอย / เงื่อนไข','','textarea')}</div>`)}${r.type==='annuity'?details('เงินบำนาญที่เชื่อมไปหน้าเกษียณ',`<div class="form-grid">${f(p+'.annuity','เงินบำนาญรับประกันต่อปี','จำนวนเงินคงที่ ไม่รวมเงินปันผลที่ไม่รับประกัน')}${f(p+'.annuityStart','อายุเริ่มรับ (ปี)','','number',null,'max="120"')}${f(p+'.annuityEnd','อายุที่รับงวดสุดท้าย','','number',null,'max="120"')}</div><p class="help">หากรับเงินแบบขั้นบันได ให้ใช้ยอดขั้นต่ำรับประกันและบันทึกตารางในรายละเอียดก่อนตรวจแผนเพิ่มเติม</p>`,true):''}${details('เบี้ยใช้สิทธิลดหย่อนปี 2569',`<p class="help">กรอกเฉพาะเบี้ยของเจ้าของแผนที่จ่ายจริงและบริษัทรับรองว่าลดหย่อนได้ ไม่ใช้เบี้ยรวมโดยอัตโนมัติ เบี้ยของคู่สมรสหรือบิดามารดาให้กรอกในหน้าภาษี</p><div class="form-grid">${f(p+'.taxLife','ชีวิตส่วนที่เข้าเกณฑ์','ไม่รวมสุขภาพและบำนาญ')}${f(p+'.taxHealth','สุขภาพส่วนที่เข้าเกณฑ์')}${f(p+'.taxAnnuity','บำนาญส่วนที่เข้าเกณฑ์','ระบบจัดวงเงินชีวิตส่วนแรกและเกษียณให้')}</div>`)}<div class="inline-note" data-policy-summary="${r.id}"></div>`,'กรมธรรม์ที่ '+(i+1))}
function protectionPage(){return box('ทะเบียนกรมธรรม์ทั้งหมด','ชีวิต สุขภาพ อุบัติเหตุ รถ บ้าน เดินทาง และความเสี่ยงอื่น',state.policies.map(policyEntry).join('')||empty('เริ่มรวบรวมความคุ้มครอง','เพิ่มกรมธรรม์ได้หลายบริษัท ทั้งของตนเองและครอบครัว'),add('policies','กรมธรรม์'))+box('ภาระที่ต้องการปกป้อง','ประเมินทุนชีวิตสำหรับเจ้าของแผน โดยใช้ยอดหนี้จากหน้าแรก',`<div class="form-grid">${f('protection.familyMonthly','เงินดูแลครอบครัว / เดือน')}${f('protection.years','ต้องการดูแลต่อ (ปี)')}${f('protection.education','เงินการศึกษาที่ยังต้องเตรียม')}${f('protection.available','สินทรัพย์พร้อมให้ครอบครัว','ไม่รวมเงินที่จัดสรรให้เป้าหมายหรือเกษียณแล้ว')}${f('protection.healthNeed','วงเงินสุขภาพที่ต้องการทบทวน')}${f('protection.welfareLife','ทุนชีวิตจากสวัสดิการ','ไม่รวมกรมธรรม์กลุ่มที่บันทึกไว้แล้ว')}${f('protection.welfareHealth','วงเงินสุขภาพสวัสดิการ','แสดงแยก ไม่บวกกับวงเงินกรมธรรม์')}${f('protection.ciYears','เงินดูแลเมื่อป่วยหนัก (ปี)')}${f('protection.incomeMonthly','รายได้ที่ต้องทดแทน / เดือน')}${f('protection.disabilityMonths','ช่วงที่ต้องทดแทนรายได้ (เดือน)')}${f('protection.welfare','สวัสดิการ / สิทธิรักษาเดิม','ประกันสังคม บัตรทอง นายจ้าง ฯลฯ','text')}</div>`)+result('protection-results')+details('อ้างอิงการจัดหมวดประกัน',`<p class="small">ประกันชีวิตรวมแบบชั่วระยะเวลา ตลอดชีพ สะสมทรัพย์ บำนาญ ควบการลงทุน และสัญญาเพิ่มเติม ส่วนประกันวินาศภัยครอบคลุมรถยนต์ อัคคีภัย ทางทะเล/ขนส่ง และเบ็ดเตล็ด เช่น สุขภาพ อุบัติเหตุ เดินทาง และความรับผิด</p><a href="https://www.oic.or.th/manual/" target="_blank" rel="noopener">คู่มือประชาชนจาก คปภ.</a>`)}
function portfolioEntry(r,i){const p='portfolios.'+i;return entry('portfolios',i,`<div class="form-grid">${f(p+'.name','ชื่อพอร์ต / กองทุน / สถาบัน','','text')}${r.type==='PVD'?'<div class="inline-note"><b>PVD • กองทุนสำรองเลี้ยงชีพ</b><p class="help">กรอกมูลค่ารวมส่วนลูกจ้างและส่วนของนายจ้างที่มีสิทธิ ไม่รวมซ้ำในสินทรัพย์อื่น</p></div>':select(p+'.type','ประเภทเงินลงทุน',portfolioTypes)}${select(p+'.purpose','เงินก้อนนี้มีไว้เพื่อ',purposeOptions(),'เลือกได้หนึ่งเป้าหมาย ป้องกันนับซ้ำ')}${f(p+'.cost','ต้นทุนคงเหลือ','ต้นทุนของหน่วยที่ยังถืออยู่')}${f(p+'.value','มูลค่าปัจจุบัน','กำไร/ขาดทุนจะคำนวณจากมูลค่าลบต้นทุน')}${f(p+'.start','เริ่มลงทุนเมื่อ','','date')}${f(p+'.unlock','วันที่เงินพร้อมใช้ / ขายได้','ตรวจเงื่อนไขถือครองของแต่ละรุ่นหน่วยลงทุน','date')}${f(p+'.monthly','เงินลงทุนต่อเดือนของคุณ','นับรวมเงินออมแผนนี้แล้ว')}${f(p+'.employer','เงินสมทบนายจ้าง / เดือน','กรอกเฉพาะส่วนที่คาดว่าจะได้สิทธิจริง')}${r.type==='PVD'?select(p+'.taxAuto','ยอดเงินสะสมสำหรับภาษี',{'true':'ประมาณการเงินสะสมต่อเดือน × 12','false':'ยอดจ่ายจริงทั้งปีตามหลักฐาน'}):''}${!r.taxAuto||r.type!=='PVD'?f(p+'.taxPaid','เงินจ่ายเองที่ใช้สิทธิภาษีปีนี้','ไม่รวมเงินสมทบนายจ้าง ไม่ใช่มูลค่าพอร์ต'):''}</div>${check(p+'.payroll','เงินสะสมของคุณหักผ่านเงินเดือน','ยอดก่อนหักจะหักให้ ยอดสุทธิจะไม่หักซ้ำ หากจ่ายจากบัญชีเองให้เอาเครื่องหมายออก')}${r.payroll?`<div class="form-grid" style="margin-top:12px">${select(p+'.incomeId','ผูกกับรายรับรายเดือน',{'':'ยังไม่ผูก / กองทุนเก่า',...Object.fromEntries(state.incomes.filter(x=>x.frequency==='monthly').map(x=>[x.id,x.name]))},'ผูกหนึ่งรายรับต่อกองทุน หากคงเงินกองทุนเก่าไว้ ให้ตั้งเงินสะสมและเงินสมทบต่อเดือนเป็น 0')}</div>`:''}<div class="form-grid" style="margin-top:12px">${f(p+'.notes','หมายเหตุ / เงื่อนไขการถือครอง','','textarea')}</div><div data-portfolio-summary="${r.id}"></div>`)}
function goalEntry(g,i){const p='goals.'+i;return entry('goals',i,`<div class="form-grid">${f(p+'.name','ชื่อเป้าหมาย','','text')}${f(p+'.target','จำนวนเงินที่ต้องการ')}${f(p+'.years','อีกกี่ปี','','number',null,'min="0.1" max="100"')}${select(p+'.priority','ลำดับความสำคัญ',{high:'จำเป็นมาก',medium:'สำคัญ',low:'ยืดหยุ่นได้'})}${f(p+'.monthly','เงินออมเพิ่มนอกพอร์ต / เดือน','ไม่รวมเงินลงทุนรายเดือนที่กรอกในพอร์ตแล้ว')}${f(p+'.rate','ผลตอบแทนสมมติสุทธิ (% ต่อปี)','ปรับได้ ไม่ใช่ผลตอบแทนรับประกัน','number',null,'max="30"')}</div>${check(p+'.todayValue','จำนวนเงินข้างต้นเป็นมูลค่าวันนี้ ต้องปรับเงินเฟ้อ','ใช้อัตราเงินเฟ้อเดียวกับหน้าเกษียณ')}<div data-goal-result="${g.id}" class="goal-output"></div>${details('คำแนะนำและแผนปฏิบัติ',`<div data-goal-advice="${g.id}" class="callout"></div>${f(p+'.recommendation','บันทึกคำแนะนำเฉพาะลูกค้า','แนวทางเก็บเงิน วิธีลงทุน วันที่เริ่ม และเงื่อนไขที่ต้องทบทวน','textarea')}`,true)}`,'เป้าหมายที่ '+(i+1))}
function goalsPage(){return box('เป้าหมายชีวิต','ระยะสั้น ≤ 3 ปี • กลาง > 3–7 ปี • ยาว > 7 ปี',state.goals.map(goalEntry).join('')||empty('เริ่มจากสิ่งที่สำคัญกับคุณ','บ้าน การศึกษา ท่องเที่ยว เงินก้อน หรือเป้าหมายอื่น ๆ'),add('goals','เป้าหมาย'))+box('พอร์ตลงทุนที่มีอยู่','บันทึกครั้งเดียว แล้วเลือกจัดสรรไปเป้าหมายหรือเกษียณ',state.portfolios.map((r,i)=>r.type==='PVD'?'':portfolioEntry(r,i)).join('')||empty('เพิ่มพอร์ตที่ถืออยู่','รวม RMF, SSF เดิม, Thai ESG และกองทุนอื่น ส่วน PVD กรอกหน้าแรก'),add('portfolios','พอร์ต'))+box('PVD ที่เชื่อมจากหน้าแรก','เป็นรายการเดียวกันกับข้อมูลการเงิน ไม่เพิ่มซ้ำในพอร์ต',result('pvd-linked'),'<a href="#finance" class="linked">แก้ไข PVD ในหน้าแรก</a>')+box('ความเสี่ยงและความพร้อม','ใช้ประกอบคำแนะนำเบื้องต้น ยังไม่ใช่แบบประเมิน suitability ของผู้ให้บริการ',`<div class="form-grid">${select('profile.risk','ความเสี่ยงที่ยอมรับได้',{low:'ต่ำ — เน้นรักษาเงินต้น',medium:'ปานกลาง — รับการลดลงได้บางส่วน',high:'สูง — รับความผันผวนระยะยาวได้'})}</div>`)+result('goals-results')}
function retirementPage(){return box('ชีวิตหลังเกษียณที่ต้องการ','ระบบดึงเงินที่จัดสรร “เพื่อเกษียณ” และกรมธรรม์บำนาญให้อัตโนมัติ',`<div class="form-grid">${f('retirement.age','อายุเกษียณ (ปี)','','number',null,'max="120"')}${f('retirement.end','อายุสิ้นสุดแผน (ปี)','ครอบคลุมจนก่อนวันเกิดอายุนี้ เช่น 90 คือค่าใช้จ่ายอายุ 60–89','number',null,'max="120"')}${f('retirement.expense','เงินใช้ต่อเดือนในมูลค่าวันนี้')}${f('retirement.inflation','เงินเฟ้อ (% ต่อปี)','','number',null,'max="30"')}${f('retirement.rate','ผลตอบแทนก่อนเกษียณ (%)','สุทธิหลังค่าธรรมเนียมและภาษี','number',null,'max="30"')}${f('retirement.postRate','ผลตอบแทนหลังเกษียณ (%)','','number',null,'max="30"')}${f('retirement.monthly','ออมเกษียณเพิ่มนอกพอร์ต / เดือน','ไม่รวมยอดลงทุนต่อเดือนในพอร์ต')}${f('retirement.legacy','เงินคงเหลือที่อยากส่งต่อ','มูลค่า ณ อายุสิ้นสุดแผน')}</div>`)+box('เงินเก็บที่เชื่อมมาจากแผน','PVD แก้ที่หน้าข้อมูลการเงิน ส่วนเงินลงทุนอื่นแก้ในหน้าเป้าหมายและพอร์ต',result('retirement-linked'),'<a href="#goals" class="linked">พอร์ตลงทุน</a>')+box('ประกันสังคมและรายได้หลังเกษียณ','ข้อมูลการส่งเงินดึงจากหน้าแรก ส่วนบำนาญให้กรอกตามประมาณการสิทธิจริง',`${result('social-retirement')}<a href="#finance" class="linked">แก้ไขข้อมูลการส่งประกันสังคมในหน้าแรก</a><div class="form-grid">${f('retirement.social','บำนาญประกันสังคมคาดการณ์ / เดือน','กรอก 0 หากเป็นสิทธิบำเหน็จเงินก้อน')}${f('retirement.socialAge','อายุเริ่มรับประกันสังคม','ต้องเข้าเงื่อนไขอายุและสิ้นสภาพผู้ประกันตน','number',null,'max="120"')}${f('retirement.other','รายได้ประจำหลังเกษียณอื่น / เดือน','เช่น บำนาญราชการ ไม่รวมกรมธรรม์บำนาญ')}${f('retirement.otherAge','อายุเริ่มรับรายได้อื่น','','number',null,'max="120"')}</div>${f('retirement.socialNote','แหล่งที่มาของประมาณการสิทธิ','วันที่ตรวจสิทธิ / ยอดในระบบ / ข้อสมมติ','textarea')}<p class="help">บำเหน็จที่จะได้รับในอนาคตไม่ควรกรอกเป็นพอร์ตปัจจุบัน หากยังไม่ได้รับเงิน ให้บันทึกในหมายเหตุเพื่อประเมินเพิ่มเติม</p>`)+box('ประกันบำนาญจากหน้าความคุ้มครอง','นับเฉพาะของเจ้าของแผนที่มีผลบังคับ และตามช่วงอายุรับเงิน',result('annuity-linked'),'<a href="#protection" class="linked">กรมธรรม์บำนาญ</a>')+result('retirement-results')+box('บันทึกแผนเกษียณ','ค่าใช้จ่ายสุขภาพ ภาระดูแลครอบครัว และสมมติฐานอื่น',f('retirement.notes','สิ่งที่ต้องทบทวน','','textarea'))}
const taxTabs={all:['ทุกอาชีพ',[]],employee:['พนักงาน / ข้าราชการ',['1']],freelance:['ฟรีแลนซ์ / ตัวแทน',['2','3']],professional:['วิชาชีพอิสระ',['6']],business:['ธุรกิจ / ค้าขาย / รับเหมา',['7','8']],investor:['ค่าเช่า / ผู้ลงทุน',['4','5']]};
function taxIncomeEntry(r,i){const p='incomes.'+i;let more='';if(r.taxType==='3')more=select(p+'.subtype','ลักษณะเงินได้',{rights:'ลิขสิทธิ์ / สิทธิอื่นที่หักค่าใช้จ่ายได้',annuity:'เงินรายปี / เงินอื่นที่หักค่าใช้จ่ายไม่ได้'});if((r.taxType==='3'&&r.subtype==='rights')||['5','6','7','8'].includes(r.taxType))more+=select(p+'.method','หักค่าใช้จ่าย',{standard:'ตามอัตราเหมา',actual:'ตามจริงที่จำเป็นและสมควร'});if(['5','6','8'].includes(r.taxType)){const rates=r.taxType==='5'?{'30':'30% บ้าน / ยานพาหนะ','20':'20% ที่ดินเกษตร','15':'15% ที่ดินอื่น','10':'10% ทรัพย์สินอื่น'}:r.taxType==='6'?{'30':'30% วิชาชีพทั่วไป','60':'60% ประกอบโรคศิลปะ'}:{'0':'0% — ยังไม่ยืนยันอัตรา',...(r.rate===40?{'40':'40% จากแผนเดิม — ต้องตรวจสูตรเฉพาะก่อนใช้'}:{}),'60':'60% เฉพาะกิจการที่กฎหมายกำหนด'};more+=select(p+'.rate','อัตราเหมาที่เข้าเกณฑ์',rates,r.taxType==='8'?'อย่าใช้อัตราเหมากับทุกธุรกิจ ตรวจลักษณะกิจการก่อน':'')}if(['3','5','6','7','8'].includes(r.taxType))more+=f(p+'.costs','ค่าใช้จ่ายตามจริงทั้งปี','ใช้เมื่อเลือกตามจริง ต้องมีหลักฐาน');return entry('incomes',i,`<div class="form-grid">${f(p+'.name','แหล่งเงินได้','','text')}${select(p+'.taxType','ประเภทเงินได้',incomeTypes)}${incomeTaxFields(r,i)}${more}</div>${check(p+'.taxInclude','นำเงินได้นี้รวมคำนวณภาษี','กรณีเลือกภาษีสุดท้ายหรือได้รับยกเว้น ให้เอาเครื่องหมายออกหลังตรวจสิทธิ')}<p class="help">${['1','2'].includes(r.taxType)?'เงินได้ 40(1) และ 40(2) หักค่าใช้จ่าย 50% รวมกันไม่เกิน 100,000 บาท':r.taxType==='4'?'ไม่หักค่าใช้จ่าย หากเลือก gross-up เงินปันผล ให้กรอกเงินได้รวมเครดิตและกรอกเครดิตในช่องภาษีชำระแล้ว ต้องตรวจเงื่อนไขเป็นรายกรณี':r.taxType==='7'?'เหมา 60% ใช้กรณีรับเหมาที่จัดหาสัมภาระในส่วนสำคัญนอกจากเครื่องมือ':'การจัดประเภทขึ้นกับลักษณะรายได้ ไม่ใช่ชื่อตำแหน่งงาน'}</p>`)}
function taxCoverage(){return box('ขอบเขตการคำนวณภาษี','ตรวจทาน 3 ต.ค.2569 • ปีภาษี 2569 คือรายได้ปี 2026 ยื่นสิ้นปีในปี 2570',`<div class="callout"><b>ใช้ประมาณการบุคคลธรรมดาที่อยู่ในไทยและยื่นแยก</b><p>มีช่องเงินได้ 40(1)–(8) และสิทธิทั่วไป แต่ไม่ได้ตรวจเงื่อนไขทุกอาชีพหรือทุกกรณีโดยอัตโนมัติ</p></div>${details('ดูรายการที่รองรับและที่ต้องตรวจแยก',table(['ส่วนของแผนภาษี','ขอบเขต'],[['เงินเดือน / ค่านายหน้า และอัตราภาษี','คำนวณค่าใช้จ่ายร่วม เพดานลดหย่อน ภาษีขั้นบันได และวิธีขั้นต่ำ'],['ประกัน / PVD / RMF / Thai ESG / ESGX','ตรวจวงเงินร่วมและแยกสิทธิ LTF เดิม แต่ต้องยืนยันคุณสมบัติและหนังสือรับรอง'],['เงินบริจาคและสิทธิพิเศษ','คำนวณเมื่อยืนยันเงื่อนไข ไม่ถือว่ามีสิทธิเพียงเพราะกรอกยอด'],['ธุรกิจ / นักแสดง / ศิลปิน / กิจการพิเศษ','มีช่องกรอกทั่วไป ยังไม่ครอบคลุมสูตรและสิทธิยกเว้นเฉพาะทุกกิจการ'],['เงินได้ต่างประเทศ / ยื่นรวมคู่สมรส / เงินออกจากงาน','ยังไม่คำนวณเฉพาะกรณี รวมถึงอนุสัญญาภาษีซ้อนและเครดิตต่างประเทศ'],['ภาษีครึ่งปี ภ.ง.ด.94','รับยอดที่ชำระแล้วไปหักได้ ยังไม่มีเครื่องคำนวณครึ่งปีแยก']]))}`)}
function specialTaxSection(){return box('4.1 สิทธิพิเศษที่อาจใช้ในปี 2569','กรอกเฉพาะส่วนของคุณที่เข้าเงื่อนไข ไม่กรอกซ้ำในสิทธิอื่น',
 details('Solar Rooftop สำหรับบ้านอยู่อาศัย — สูงสุด 200,000 บาท',`<p class="help">หนึ่งระบบ ใช้สิทธิครั้งเดียวในปีที่เชื่อมต่อโครงข่าย กฟน./กฟภ. สำเร็จ ต้องจ่ายตั้งแต่ 3 มี.ค.2569 ถึง 31 ธ.ค.2571 ให้ผู้ประกอบการ VAT และได้รับ e-Tax Invoice แบบเต็มรูป ไม่ใช้รายจ่ายเดียวกันซ้ำสิทธิอื่น ช่องนี้ใช้สำหรับปีที่เชื่อมต่อใน 2569 เท่านั้น</p><div class="form-grid two">${f('tax.solar','ค่าอุปกรณ์และติดตั้งที่เข้าเกณฑ์','ยอดจ่ายจริงที่มีสิทธิ รวม VAT ไม่ใช่จำนวนภาษีที่จะได้คืน')}${f('tax.solarConnected','วันที่เชื่อมต่อโครงข่ายสำเร็จ','','date')}</div>${check('tax.solarConfirmed','ยืนยันหนึ่งระบบ ไม่เคยใช้สิทธินี้ ตรวจช่วงวันจ่าย ผู้รับเงิน e-Tax Invoice และเงื่อนไขอื่นแล้ว')}`)+
 details('งานศิลปะสาขาทัศนศิลป์ — สูงสุด 100,000 บาท',`<p class="help">มาตรการซื้อช่วงปี 2568–2570 กรอกเฉพาะยอดซื้อปี 2569 จากศิลปินหรือผู้ขายที่เข้าเกณฑ์ มีใบกำกับภาษี/ใบรับ และหลักฐานรับรองงานศิลปะ ไม่ใช่งานศิลปะทุกชิ้น</p>${f('tax.art','ยอดซื้องานศิลปะที่เข้าเกณฑ์ปี 2569')}${check('tax.artConfirmed','ตรวจศิลปิน ผู้ขาย รายละเอียดงาน หลักฐาน และช่วงเวลาที่เข้าเงื่อนไขแล้ว')}`)+
 details('สร้างบ้านตามสัญญาเดิม — ใช้สิทธิปีที่สร้างเสร็จ',`<p class="help">สัญญาและเริ่มสร้างต้องอยู่ในช่วง 9 เม.ย.2567–31 ธ.ค.2568 จำกัดหนึ่งหลัง ผู้รับจ้าง VAT และชำระอากรสัญญาผ่านอินเทอร์เน็ต ใช้วันที่สิ้นสุดก่อสร้างตามสัญญา/ใบอนุญาต/ใบรับแจ้ง แล้วแต่วันใดหลังสุด ไม่ใช่ค่าซื้อบ้านหรือซื้อที่ดินทั่วไป</p><div class="form-grid">${f('tax.homeContract','วันทำสัญญา','','date')}${f('tax.homeStarted','วันเริ่มก่อสร้าง','','date')}${f('tax.homeCompleted','วันสิ้นสุดตามเกณฑ์ (ต้องเป็นปี 2569)','','date')}${f('tax.homeBuild','ยอดสิทธิที่ตรวจและจัดสรรแล้ว','กรอกยอดลดหย่อน ไม่ใช่ค่าก่อสร้าง: 10,000 ต่อค่าก่อสร้างทุก 1 ล้านบาท สูงสุด 100,000 และตรวจส่วนแบ่งผู้ร่วมสัญญา')}</div>${check('tax.homeConfirmed','ตรวจสัญญา อากร VAT ใบอนุญาต ปีเสร็จ และยอดสิทธิส่วนของคุณแล้ว')}`))}
function taxPage(){const selected=state.incomes.map((r,i)=>({r,i})).filter(({r})=>taxTab==='all'||taxTabs[taxTab][1].includes(r.taxType));return taxCoverage()+`<div class="callout warn"><b>ประมาณการปีภาษี 2569 • ตรวจแหล่งข้อมูล 3 ต.ค. 2569</b><p>ใช้สิทธิพื้นฐานและกฎปี 2569 ที่ยืนยันได้ แบบสิ้นปี 2569 ยังไม่ปรากฏในหน้ารวมแบบที่ตรวจพบ มาตรการชั่วคราวหรือสิทธิเฉพาะกรณีต้องยืนยันเพิ่มเติมก่อนยื่นจริง</p></div>`+box('1. เงินได้ของทุกอาชีพ','เลือกแท็บเพื่อกรอกได้ง่าย ระบบยังรวมเงินได้ทุกแท็บในการคำนวณ',`<div class="tabs" role="tablist">${Object.entries(taxTabs).map(([k,v])=>`<button role="tab" aria-selected="${taxTab===k}" class="${taxTab===k?'selected':''}" data-tax-tab="${k}">${v[0]}</button>`).join('')}</div>${selected.map(({r,i})=>taxIncomeEntry(r,i)).join('')||empty('ยังไม่มีเงินได้ในกลุ่มนี้','เพิ่มรายการใหม่ หรือเลือกแท็บทุกอาชีพ')}<p class="help">ยอดรายรับสุทธิสำหรับ Cash Flow แก้ในหน้าแรก ส่วนหน้านี้ใช้ยอดก่อนหักภาษีทั้งปี</p>`,add('taxIncome','แหล่งเงินได้'))+box('2. ส่วนตัวและครอบครัว','ระบุเฉพาะจำนวนคนและยอดที่คุณมีสิทธิตามเงื่อนไข',`<div class="form-grid">${select('tax.maritalDuringYear','การสมรสตามกฎหมายในปีภาษี',{none:'ไม่มีการสมรสในปีนี้',all:'สมรสตลอดปี',during:'จดทะเบียนระหว่างปี',ended:'หย่า / คู่สมรสเสียชีวิตระหว่างปี'})}${select('tax.spouseIncome','คู่สมรสมีเงินได้ในปีภาษีหรือไม่',{unknown:'ยังไม่ยืนยัน',none:'ไม่มีเงินได้พึงประเมิน',yes:'มีเงินได้ — ยื่นแยก'})}</div>${check('tax.spouseFullYear','สมรสตลอดปีภาษี — ใช้ตรวจสิทธิเบี้ยชีวิตคู่สมรส')}${check('tax.spouse','ใช้สิทธิลดหย่อนคู่สมรส 60,000 บาท','จดทะเบียนสมรสตามกฎหมาย และคู่สมรสไม่มีเงินได้พึงประเมินในปีภาษีนี้ เลือกเมื่อเข้าเงื่อนไขทั้งสองข้อ ระบบจะนำค่าลดหย่อนไปคำนวณอัตโนมัติ')}<div class="form-grid">${f('tax.children','บุตรที่เข้าเกณฑ์ (คน)','โดยทั่วไปต่ำกว่า 20 ปี หรือเรียนไม่เกิน 25 ปี และรายได้เข้าเกณฑ์ บุตรบุญธรรมมีข้อจำกัด')}${f('tax.extraChildren','บุตรที่ได้เพิ่มอีก 30,000 (คน)','บุตรชอบด้วยกฎหมายลำดับที่ 2 เป็นต้นไป เกิดตั้งแต่ปี 2561')}${f('tax.parents','บิดามารดาที่เข้าเกณฑ์ (คน)','อายุ 60+ รายได้ไม่เกิน 30,000/ปี ไม่ใช้สิทธิซ้ำพี่น้อง รวมคู่สมรสเฉพาะที่เข้าเงื่อนไข','number',null,'max="4" step="1"')}${f('tax.disabled','คนพิการที่อุปการะตามเกณฑ์ (คน)','มีหลักฐานและไม่ใช้สิทธิซ้ำ')}${f('tax.seniorExempt','ยกเว้นเงินได้ผู้สูงอายุ / พิการ','เฉพาะผู้เข้าเกณฑ์ สูงสุดรวม 190,000 บาท ไม่ใช้ซ้ำสองสถานะ','number',null,'max="190000"')}${select('tax.seniorType','ใช้สิทธิยกเว้นกับเงินได้ประเภท',incomeTypes,'ใช้สิทธิกับประเภทเดียวตามลำดับรายการ หากแบ่งหลายประเภทหรือวิธีหักค่าใช้จ่ายต่างกัน ให้ตรวจเพิ่มเติม')}${f('tax.childbirth','ฝากครรภ์ / คลอดบุตรที่มีสิทธิ','หลังหักสวัสดิการ ใช้ตามจริงสูงสุด 60,000 บาทต่อครรภ์')}</div>`)+box('3. ประกันและการออมที่เชื่อมจากแผน','กรอกยอดตามหนังสือรับรองที่หน้ากรมธรรม์และพอร์ต ข้อมูลนี้ไม่หัก Cash Flow ซ้ำ',result('tax-linked')+`<div class="form-grid">${f('tax.parentHealth','เบี้ยสุขภาพบิดามารดา','ยอดที่คุณมีสิทธิหลังแบ่งกับผู้ร่วมจ่าย สูงสุด 15,000')}${f('tax.spouseLife','เบี้ยชีวิตคู่สมรสไม่มีเงินได้','เฉพาะเข้าเกณฑ์ สูงสุด 10,000')}<div class="inline-note"><b>ประกันสังคมเชื่อมจากหน้าแรก</b><p class="help">ปรับยอดจ่ายจริงหรือประมาณการในหน้าข้อมูลการเงิน</p><a href="#finance" class="linked">แก้ไขประกันสังคม</a></div>${select('tax.esgxMode','สิทธิ LTF → ESGX',{manual:'กรอกยอดสิทธิปีนี้ตามใบรับรอง',calculate:'คำนวณจากมูลค่าโอนที่เข้าเกณฑ์ปี 2568'})}${state.tax.esgxMode==='calculate'?f('tax.esgxTransferred','มูลค่า LTF ที่โอนตามมาตรการปี 2568')+check('tax.esgxConfirmed','ยืนยันการโอนครบตามเงื่อนไขและหลักฐานปี 2568'):f('tax.esgxCarry','สิทธิทยอย LTF → ESGX ปีนี้','ยอดตามใบรับรอง สูงสุดปีละ 50,000')}<p class="help">ปี 2569–2572 แบ่งส่วนที่เกิน 300,000 บาทเท่ากัน 4 ปี ภายใต้วงเงินโอนใช้สิทธิรวม 500,000 บาท</p></div><p class="help">SSF เดิมยังเป็นสินทรัพย์ แต่ไม่ใช้ยอดซื้อใหม่ลดหย่อนปี 2569 • Thai ESG และ ESGX ซื้อใหม่ใช้วงเงินร่วมกัน • เงินสมทบนายจ้างไม่ใช่ค่าลดหย่อนของคุณ</p>`)+box('4. ที่อยู่อาศัย การบริจาค และสิทธิอื่น',`กรอกเฉพาะยอดที่เข้าเงื่อนไขและมีหลักฐาน`,`${result('tax-home')}<div class="form-grid">${f('tax.donation','บริจาคทั่วไปที่เข้าเกณฑ์','ยอดจ่ายจริง ก่อนใช้เพดาน 10% ตั้งแต่ 1 ม.ค.2569 วัด มูลนิธิ สมาคม กองทุนและองค์กรตามประกาศต้องผ่าน e-Donation')}${f('tax.doubleDonation','บริจาคที่มีสิทธิ 2 เท่า','กรอกยอดจ่ายจริง ไม่คูณเอง ต้องมีกฎหมายให้สิทธิแก่ผู้รับและช่วงเวลานั้น การมี e-Donation อย่างเดียวไม่ได้แปลว่าได้ 2 เท่า')}${f('tax.political','บริจาคพรรคการเมือง','สูงสุด 10,000 บาท')}${f('tax.socialEnterprise','ลงทุนวิสาหกิจเพื่อสังคมที่เข้าเกณฑ์','สูงสุด 100,000 บาท')}${f('tax.other','สิทธิเฉพาะกรณีอื่นที่ตรวจแล้ว','ไม่รวมสิทธิที่กรอกในช่องอื่น')}${f('tax.otherSource','ชื่อสิทธิ / กฎหมาย / ลิงก์อ้างอิง','','text')}</div>${check('tax.donationConfirmed','ยืนยันผู้รับและหลักฐานบริจาคทั่วไป รวม e-Donation ตามที่กฎหมายกำหนด')}${check('tax.doubleDonationConfirmed','ยืนยันกฎหมายที่มีผลใช้บังคับ ผู้รับ ช่วงเวลา และหลักฐานที่ให้สิทธิบริจาค 2 เท่า')}${check('tax.otherConfirmed','ยืนยันว่าได้ตรวจเงื่อนไขและยอดสิทธิเฉพาะกรณีปี 2569 แล้ว')}<p class="help">ไม่ได้ใส่ Easy E-Receipt ปี 2568 หรือมาตรการท่องเที่ยวเก่าให้อัตโนมัติ เพื่อไม่ให้ใช้สิทธิผิดปี</p>`)+specialTaxSection()+box('5. ภาษีชำระแล้วและทดลองวางแผน',`ภาษีหัก ณ ที่จ่ายดึงจากแต่ละแหล่งเงินได้`, `<div class="form-grid">${f('tax.halfPaid','ภาษีครึ่งปี ภ.ง.ด.94 ที่ชำระแล้ว')}${f('tax.credit','เครดิตภาษีอื่นที่ตรวจสิทธิแล้ว','เช่น เครดิตเงินปันผล ต้องกรอกเงินได้ gross-up ให้สอดคล้อง')}${f('tax.extraPlan','ทดลองออมลดหย่อนเพิ่ม','จำลองวงเงิน RMF + Thai ESG ที่ยังเหลือ ไม่เปลี่ยน Cash Flow จนกว่าจะจัดสรรจริง')}</div>${f('tax.notes','ประเด็นภาษีที่ต้องตรวจเพิ่มเติม','เงินได้ต่างประเทศ เครดิตภาษี ยื่นรวมคู่สมรส กิจการพิเศษ ฯลฯ','textarea')}`)+result('tax-results')+details('หลักเกณฑ์และแหล่งข้อมูล',`<p class="small">แบบนี้ใช้วางแผนบุคคลธรรมดาผู้มีถิ่นที่อยู่ไทยที่ยื่นแยก ไม่ใช่แบบยื่นจริง ยังไม่คำนวณอนุสัญญาภาษีซ้อน รายได้ต่างประเทศ การแยกภาษีเงินออกจากงาน หรือสิทธิธุรกิจเฉพาะโดยอัตโนมัติ</p>${sourceHTML}`)}
function reportPage(){return plainBox('ที่มาของผลลัพธ์','แยกข้อมูลที่บันทึกกับสมมติฐานก่อนนำไปใช้',table(['ประเภท','ที่มา'],[['ข้อมูลที่กรอก','รายรับ รายจ่าย สินทรัพย์ หนี้ และกรมธรรม์ — ยังไม่ได้ตรวจเอกสารภายนอก'],['ประมาณการ','ผลตอบแทน เงินเฟ้อ รายได้จากโหมดประมาณการ และภาษี'],['ยังไม่ยืนยัน',Object.values(meta(state).unknown).filter(Boolean).length+' ช่อง'],['สถานะแผน',state.profile.example?'ข้อมูลสมมติทั้งหมด':'แผนของผู้ใช้']]))+`<div class="no-print" style="margin-bottom:20px"><button class="primary" data-action="print">พิมพ์ / บันทึก PDF</button></div>${result('report-results')}`+box('แผนลงมือทำร่วมกัน','กำหนดสิ่งที่จะทำและวันนัดทบทวน',`<div class="form-grid two">${f('review.actions','รายการที่ตกลงทำต่อ','','textarea')}${f('review.notes','ข้อสังเกต / ข้อมูลที่ยังต้องขอเพิ่ม','','textarea')}${f('review.nextDate','วันทบทวนแผนครั้งถัดไป','','date')}</div>`)}
function advice(g,cf){const tips=[];if(cf.remaining<0)tips.push('งบรวมติดลบ ควรลดรายจ่าย ปรับเงินออม หรือเลื่อนเป้าหมายก่อนเพิ่มความเสี่ยงลงทุน');if(cf.reserves<cf.reserveTarget)tips.push('เงินสำรองยังไม่ถึงเป้า ควรแบ่งเงินเติมสภาพคล่องควบคู่กัน');if(g.years<=3)tips.push('เป้าหมายใกล้: พิจารณาเงินฝากหรือสินทรัพย์สภาพคล่องสูงที่มูลค่าผันผวนน้อย ตรวจความคุ้มครองเงินฝากและความเสี่ยงกองทุน');else if(g.years<=7)tips.push('เป้าหมายระยะกลาง: พิจารณากระจายสินทรัพย์ให้สอดคล้องกับความเสี่ยงที่รับได้ และทยอยลดความผันผวนเมื่อใกล้ใช้เงิน');else tips.push('เป้าหมายระยะยาว: พิจารณาลงทุนสม่ำเสมอ กระจายสินทรัพย์ และทบทวนสัดส่วนเป็นระยะ');if(state.profile.risk==='low')tips.push('คุณระบุว่ารับความเสี่ยงต่ำ ควรเลือกแผนที่รับการขาดทุนชั่วคราวได้จริง');if(g.rate>6&&g.years<=3)tips.push('สมมติฐานผลตอบแทนสูงสำหรับเป้าหมายใกล้ ควรทดสอบผลตอบแทนต่ำลง');return tips.map(x=>`<p>${x}</p>`).join('')}
function financeResults(cf){return`<div class="stats">${stat('รายรับเฉลี่ย / เดือน',money(cf.income/12),'จากรายการรายรับทั้งปี')}${stat('รายจ่ายก่อนออม / เดือน',money((cf.expenses+cf.premiums)/12+cf.debtMonthly),'รวมค่างวดและงบเฉลี่ยเบี้ย')}${stat('เหลือก่อนออม / เดือน',money(cf.free),'ก่อนออมเพิ่มจากเงินสุทธิ',cf.free<0?'negative':'green')}${stat('เหลือหลังออม / เดือน',money(cf.remaining),'รวมทุกเป้าหมายและพอร์ต',cf.remaining<0?'negative':'green')}</div><div class="grid"><section class="card"><h2>ฐานะการเงิน ณ วันนี้</h2>${row('สินทรัพย์รวม (รวมพอร์ต)',money(cf.assetTotal))}${row('หนี้คงเหลือ',money(cf.debtTotal))}${row('สินทรัพย์สุทธิ',money(cf.net))}${row('เงินสำรองฉุกเฉิน',money(cf.reserves))}${row('สำรองรองรับได้',cf.runway.toFixed(1)+' เดือน')}${progress('เงินสำรองเทียบเป้าหมาย',cf.reserves,cf.reserveTarget)}</section><section class="card"><h2>เงินที่เชื่อมจากหน้าอื่น</h2>${row('เบี้ยประกันรวม / ปี',money(cf.premiums))}${row('หักจากรายรับก่อนหัก / เดือน',money(cf.payrollDeductions/12))}${row('ประกันสังคมจ่ายเองนอกสลิป / เดือน',money(cf.socialOwn))}${row('เงินลงทุนจาก Cash Flow / เดือน',money(cf.portfolioCash))}${row('ออมเพิ่มเป้าหมาย / เดือน',money(cf.goalMonthly))}${row('ออมเกษียณเพิ่ม / เดือน',money(state.retirement.monthly))}<div class="callout">เงินหักผ่านเงินเดือนที่ระบุในพอร์ตจะไม่ถูกหักซ้ำจากรายรับสุทธิ ส่วนเบี้ยประกันใช้เงินกันไว้เฉลี่ยรายเดือน</div></section></div>${details('งบกันเงินเฉลี่ยรายเดือน',table(['เดือน','เงินเหลือเมื่อกันเบี้ยเฉลี่ย'],cf.months.map(m=>[months[m.month-1],money(m.averageRemaining)])))}${box('กระแสเงินสดรายเดือน','ตามปีภาษีที่เลือก เบี้ยตามเดือนครบกำหนด หนี้ลดต้นลดดอกเริ่มจำลองงวดแรกเดือนมกราคม ไม่ใช่บัญชีธุรกรรมย้อนหลัง',table(['เดือน','รับจริง','รายจ่ายที่กรอก','เหลือหลังหนี้ เบี้ย และออม'],cf.months.map(m=>[months[m.month-1],money(m.income),money(m.expense),`<span class="${m.remaining<0?'negative':'green'}">${m.remaining===null?'ยังขาดวันชำระเบี้ย':money(m.remaining)}</span>`])))}`}
function protectionResults(pr,cf){return`<div class="stats">${stat('กรมธรรม์ทั้งหมด',state.policies.length,'รวมทุกคนในครอบครัว')}${stat('เบี้ยปัจจุบัน / ปี',money(cf.premiums),'เฉพาะกรมธรรม์ที่ยังชำระ')}${stat('ทุนชีวิตของเจ้าของแผน',money(pr.cover),'ทุนทั่วไป ไม่รวมอุบัติเหตุซ้ำ')}${stat('ช่องว่างทุนชีวิต',money(pr.gap),'ตามภาระที่กรอก',pr.gap>0?'warning':'green')}</div>${box('สิ่งที่ควรทบทวน','วงเงินต่างชนิดไม่ควรรวมเป็นยอดความคุ้มครองเดียว',row('ทุนชีวิตตามความต้องการ',money(pr.need))+row('กรมธรรม์สุขภาพของเจ้าของแผน',pr.healthCount+' ฉบับ')+row('ทุนโรคร้ายแรงรวมตามที่กรอก',money(pr.ci))+row('เงินดูแลครอบครัวเมื่อป่วยหนักตามช่วงที่เลือก',money(pr.ciNeed))+row('ส่วนที่ยังขาดเทียบทุนโรคร้ายแรงที่กรอก',money(Math.max(0,pr.ciNeed-pr.ci)))+row('เงินทดแทนรายได้เป้าหมาย',money(pr.disabilityNeed))+row('ทุนทุพพลภาพที่กรอก (ตรวจนิยามก่อนเปรียบเทียบ)',money(pr.disability))+row('วงเงินสุขภาพที่ต้องการทบทวน',money(state.protection.healthNeed))+row('สวัสดิการสุขภาพ (แยกจากกรมธรรม์)',money(state.protection.welfareHealth))+row('กรมธรรม์หมดอายุตามวันที่',pr.expired+' ฉบับ')+'<p class="help">วงเงินสุขภาพไม่บวกตรง ๆ เพราะฐานวงเงิน ข้อยกเว้น และการเบิกซ้ำต่างกัน ทุนโรคร้ายแรงอาจมีเงื่อนไขจ่ายร่วม/หักทุน ต้องตรวจกรมธรรม์ก่อนใช้จริง</p>')}`}
function goalsResults(cf,gs){const required=sum(gs,g=>g.required),contribution=sum(gs,g=>g.monthlyTotal);return`<div class="stats">${stat('เป้าหมายทั้งหมด',gs.length,'แยกระยะเวลาและความสำคัญ')}${stat('ควรออมเป้าหมายรวม / เดือน',money(required),'ตามสมมติฐานแต่ละเป้าหมาย')}${stat('ออมตามแผนเป้าหมาย / เดือน',money(contribution),'รวมพอร์ตที่ผูกเป้าหมาย')}${stat('เงินคงเหลือทั้งแผน / เดือน',money(cf.remaining),'หลังทุกเป้าหมายและเกษียณ',cf.remaining<0?'negative':'green')}</div>${box('ศักยภาพเทียบกับเป้าหมาย','เปรียบเทียบทุกข้อ โดยไม่ใช้เงินต้นหรือเงินออมก้อนเดียวซ้ำ',table(['เป้าหมาย','ต้องออม / เดือน','ตั้งไว้ / เดือน','ยังต้องเพิ่ม / เดือน'],gs.map(g=>[esc(g.name),money(g.required),money(g.monthlyTotal),money(Math.max(0,g.required-g.monthlyTotal))]))+`<div class="callout ${cf.remaining<0?'warn':''}">เงินเพิ่มที่แต่ละเป้าหมายต้องการรวม ${money(sum(gs,g=>Math.max(0,g.required-g.monthlyTotal)))} บาท/เดือน เทียบกับเงินว่างหลังจัดสรร ${money(Math.max(0,cf.remaining))} บาท/เดือน</div>`)}`}
function retirementResults(r){if(r.invalid)return'<div class="callout error">ตรวจอายุเกษียณและอายุสิ้นสุดแผนก่อนคำนวณ หน้ากรอกยังใช้งานต่อได้</div>';return`<div class="stats">${stat('เงินก้อนที่ต้องมีวันเกษียณ',money(r.target),'หักรายได้ประจำตามแต่ละปีแล้ว')}${stat('เงินที่คาดว่าจะสะสมได้',money(r.future),'ตามเงินต้นและเงินออมที่จัดสรร')}${stat('เงินเกษียณที่ยังขาด',money(r.gap),'ยังไม่รวมความผันผวน',r.gap>0?'warning':'green')}${stat('ควรออมเพิ่มนอกพอร์ต / เดือน',money(r.extraNeeded),r.years===0?'เกษียณแล้ว ตรวจช่องว่างเงินก้อน':'หักเงินลงทุนรายเดือนที่เชื่อมมาแล้ว')}</div>${box('เปรียบเทียบสมมติฐานผลตอบแทน','กรณีต่ำ–ฐาน–สูง ไม่ใช่ความน่าจะเป็นหรือผลตอบแทนรับประกัน',table(['กรณี','ก่อน / หลังเกษียณ','เงินก้อนเป้าหมาย','คาดว่าสะสมได้','ต้องออมเพิ่มจากแผน / เดือน'],retirementScenarios(state).map(x=>[x.label,`${x.rate}% / ${x.postRate}%`,money(x.target),money(x.future),money(Math.max(0,x.extraNeeded-state.retirement.monthly))])))}${box('ความพร้อมและจังหวะใช้เงิน','ถอนค่าใช้จ่ายต้นปี จนก่อนอายุสิ้นสุดแผน',row('ค่าใช้จ่ายต่อเดือนในมูลค่าเงินวันนี้',money(state.retirement.expense))+row('จำนวนปีที่ครอบคลุม',r.duration+' ปี (อายุ '+state.retirement.age+'–'+(state.retirement.end-1)+')')+row('ค่าใช้จ่ายเดือนแรก ณ อายุเกษียณ',money(r.firstExpense))+row('เงินต้นที่นำมาคำนวณ',money(r.capital))+row('เงินออมรวมเพื่อเกษียณ / เดือน',money(r.monthly))+progress('ความพร้อมตามสมมติฐาน',r.future,r.target)+(r.locked.length?'<div class="callout warn">ไม่นำ '+r.locked.map(p=>esc(p.name)).join(', ')+' มาคิดเงินต้น เพราะยังไม่พร้อมใช้ ณ วันเกษียณ ต้องวางแผนเงินช่วงรอยต่อเพิ่มเติม</div>':'')+details('ตารางรายได้และค่าใช้จ่ายหลังเกษียณ',table(['อายุ','ค่าใช้จ่าย / ปี','รายได้ประจำ / ปี','ถอนจากเงินเก็บ / ปี'],r.timeline.map(t=>[t.age,money(t.expense),money(t.pension),money(t.need)])))+'<p class="help">แบบจำลองผลตอบแทนคงที่ รายได้ประจำและบำนาญคงที่ ไม่มีการนำเงินบำนาญส่วนเกินไปลงทุนต่อ ไม่ใช่การจำลองความเสี่ยงตลาดหรือความน่าจะเป็นที่เงินพอ</p>')}`}
function taxLinked(t){return row('ประกันสังคม'+(state.tax.socialAuto?' (ประมาณการทั้งปี)':' (ตามหลักฐาน)'),money(socialAnnual(state)))+ table(['รายการที่เชื่อมมา','ยอดก่อนตรวจเพดาน'],[['เบี้ยชีวิตเจ้าของแผนตามหนังสือรับรอง',money(sum(state.policies.filter(p=>p.insured==='self'),p=>n(p.taxLife)))],['เบี้ยสุขภาพเจ้าของแผนตามหนังสือรับรอง',money(sum(state.policies.filter(p=>p.insured==='self'),p=>n(p.taxHealth)))],['เบี้ยบำนาญเจ้าของแผนตามหนังสือรับรอง',money(sum(state.policies.filter(p=>p.insured==='self'),p=>n(p.taxAnnuity)))],...['RMF','PVD','GPF','NSF','teacher','ThaiESG','ThaiESGX'].map(type=>[portfolioTypes[type],money(sum(state.portfolios.filter(p=>p.type===type),p=>portfolioTax(p,state)))])])+`<p class="help">กลุ่มเกษียณหลังใช้เพดานรวม ${money(t.retirement)} บาท • Thai ESG/ESGX หลังใช้เพดาน ${money(t.esg)} บาท</p>`}
function taxResults(t){return`<div class="stats">${stat('เงินได้ก่อนหักทั้งปี',money(t.gross),t.form+' โดยประมาณ')}${stat('เงินได้สุทธิทางภาษี',money(t.net),'หลังค่าใช้จ่ายและลดหย่อน')}${stat('ภาษีประมาณการ',money(t.tax),'เปรียบเทียบวิธีปกติกับขั้นต่ำแล้ว')}${stat(t.balance<0?'คาดว่าขอคืน':'คาดว่าชำระเพิ่ม',money(Math.abs(t.balance)),'หลังหักยอดชำระแล้ว',t.balance<0?'green':'warning')}</div><div class="grid"><section class="card"><h2>ลำดับคำนวณภาษี</h2>${row('เงินได้พึงประเมิน',money(t.gross))}${row('ค่าใช้จ่ายตามประเภทเงินได้',money(t.costs))}${row('ค่าลดหย่อนก่อนบริจาค',money(t.deductions))}${row('บริจาคที่หักได้รวม',money(t.doubleDonation+t.donation))}${row('เงินได้สุทธิ',money(t.net))}${row('ภาษีตามขั้นบันได',money(t.tax1))}${row('ภาษีวิธีขั้นต่ำที่ต้องเปรียบเทียบ',money(t.tax2))}${row('ภาษีหัก ณ ที่จ่าย + จ่ายแล้ว + เครดิต',money(t.paidTax))}${t.halfYear?'<div class="callout warn">มีเงินได้ 40(5)–(8): ตรวจหน้าที่ยื่น ภ.ง.ด.94 ครึ่งปีเพิ่มเติม ระบบนี้คำนวณประมาณการทั้งปี</div>':''}</section><section class="card"><h2>พื้นที่สำหรับวางแผนเพิ่ม</h2>${row('วงเงิน RMF ที่ยังเหลือโดยประมาณ',money(t.moreRMF))}${row('วงเงิน Thai ESG/ESGX ที่ยังเหลือ',money(t.moreESG))}${row('ยอดทดลองออมที่นำมาคิดได้',money(t.extra))}${row('ภาษีคาดว่าลดลงจากยอดทดลอง',money(t.save))}<div class="callout">ใช้เงินออมที่เหลือและความเหมาะสมของการลงทุนเป็นหลัก การซื้อเพิ่มลดภาษีเพียงบางส่วนของเงินที่จ่าย และมีเงื่อนไขถือครอง</div></section></div>${box('สิทธิที่นำมาคำนวณจริง','รายการที่มีเพดานจะถูกจำกัดอัตโนมัติ เงื่อนไขส่วนบุคคลยังต้องตรวจหลักฐาน',table(['สิทธิ','ยอดใช้คำนวณ'],t.parts.filter(p=>p[1]>0).map(([a,b])=>[a,money(b)])))}`}
function reportResults(cf,gs,r,t,pr){return`<div class="stats">${stat('สินทรัพย์สุทธิ',money(cf.net),'วันที่ '+esc(state.profile.asOf))}${stat('เงินเหลือหลังออม / เดือน',money(cf.remaining),'',cf.remaining<0?'negative':'green')}${stat('เป้าหมายที่วางไว้',gs.length,'ไม่รวมแผนเกษียณ')}${stat('ภาษีประมาณการ 2569',money(t.tax),'ไม่ใช่ยอดยื่นแบบจริง')}</div><div class="grid"><section class="card"><h2>สามเหลี่ยมการเงิน</h2><div class="pyramid"><div>ส่งต่อทรัพย์สิน</div><div>เป้าหมาย • ลงทุน • เกษียณ</div><div>สภาพคล่อง • หนี้ • ความคุ้มครอง</div></div><p class="help">ทบทวนผู้รับผลประโยชน์และเงินส่งต่อควบคู่กับแผน การจัดทำพินัยกรรมและภาษีมรดกต้องประเมินเพิ่มเติม</p></section><section class="card"><h2>ลำดับที่ควรทำต่อ</h2>${row('1. เงินสำรองที่ยังขาด',money(Math.max(0,cf.reserveTarget-cf.reserves)))}${row('2. ช่องว่างทุนชีวิต',money(pr.gap))}${row('3. เงินออมเป้าหมายที่ยังต้องเพิ่ม / เดือน',money(sum(gs,g=>Math.max(0,g.required-g.monthlyTotal))))}${row('4. เงินเกษียณที่ยังขาด',r.invalid?'ตรวจอายุ':money(r.gap))}${row('5. ภาษีคาดว่าชำระเพิ่ม / (คืน)',money(t.balance))}<p class="help">ลำดับนี้เป็นจุดเริ่มต้น ให้ปรับตามความจำเป็นของครอบครัวและข้อจำกัดจริง</p></section></div>${box('เป้าหมายและเงินที่จัดสรร','เงินต้นและเงินออมจากพอร์ตเชื่อมเข้าข้อที่เลือกเพียงครั้งเดียว',table(['เป้าหมาย','เงินต้น','คาดว่าจะมี','เป้าหมายเงินก้อน','ต้องเพิ่ม / เดือน'],gs.map(g=>[esc(g.name)+'<br><small>'+g.term+' · '+g.years+' ปี</small>',money(g.capital),money(g.future),money(g.targetValue),money(Math.max(0,g.required-g.monthlyTotal))])))}${box('ความคุ้มครองและสิทธิเกษียณ','ตรวจฐานวงเงินและเงื่อนไขกับกรมธรรม์',row('เบี้ยประกันรวมปัจจุบัน / ปี',money(cf.premiums))+row('ทุนชีวิตเจ้าของแผน',money(pr.cover))+row('อายุเกษียณ / สิ้นสุดแผน',state.retirement.age+' / '+state.retirement.end+' ปี')+row('เงินก้อนเกษียณเป้าหมาย',r.invalid?'—':money(r.target))+row('เงินคาดการณ์วันเกษียณ',r.invalid?'—':money(r.future)))}${warnings(state).length?'<div class="callout warn"><b>รายการที่ต้องตรวจ</b><ul>'+warnings(state).map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul></div>':''}${box('คำแนะนำเฉพาะแต่ละเป้าหมาย','บันทึกโดยผู้วางแผน',gs.filter(g=>g.recommendation).map(g=>`<h3>${esc(g.name)}</h3><p>${esc(g.recommendation).replace(/\n/g,'<br>')}</p>`).join('')||'<p class="muted small">ยังไม่มีบันทึกคำแนะนำเฉพาะ</p>')}${box('สมมติฐานและขอบเขต',`จัดทำ ${new Date().toLocaleDateString('th-TH')} • เงินเฟ้อ ${state.retirement.inflation}% • ก่อนเกษียณ ${state.retirement.rate}% • หลังเกษียณ ${state.retirement.postRate}%`, '<p class="small">ออมปลายเดือน ผลตอบแทนสุทธิคงที่ ไม่รับประกันผลตอบแทน คำนวณค่าใช้จ่ายเกษียณต้นปี รายได้บำนาญตามจำนวนคงที่ที่กรอก ภาษีเป็นประมาณการปี 2569 ตามข้อมูลและเงื่อนไขที่ยืนยัน ณ 3 ต.ค. 2569</p>'+details('แหล่งอ้างอิง',sourceHTML))}`}
function taxIncomeSummary(id){if(unknownFor(state,'tax'))return '<p class="help">ยังมีข้อมูลที่กระทบภาษีไม่ยืนยัน ดูรายการข้อมูลที่ต้องเติม</p>';const r=state.incomes.find(x=>x.id===id);if(!r)return '';const t=incomeTax(state,r);return row('เงินได้ที่นำเข้าภาษี'+(t.coveredBy?' (รวมในเงินเดือนแล้ว)':t.estimated?' (ประมาณการ)':' (ยอดที่กรอก)'),money(t.gross))+row('ภาษีหักแล้วที่นำเข้าคำนวณ',money(t.withheld));}
function debtSummary(id){if(Object.entries(meta(state).unknown).some(([k,v])=>v&&k.startsWith('debts.'+id+'.')&&!k.endsWith('.homeInterest')))return '<p class="callout warn">ยืนยันข้อมูลหนี้ก่อนดูตาราง</p>';const d=state.debts.find(x=>x.id===id);if(!d)return '';const t=debtSchedule(d);if(!t.supported)return '<p class="help">ใช้ค่างวดตามสัญญา ไม่แปลง Flat rate เป็นลดต้นลดดอก ดอกเบี้ยบ้านภาษีใช้ใบรับรองแยก</p>';if(t.unpayable)return '<p class="callout warn">ค่างวดไม่พอปิดหนี้ หรือระยะเวลาจำลองเกิน 100 ปี</p>';const base=debtSchedule({...d,extra:0});return row('ปิดหนี้ประมาณ',t.months+' เดือนจากงวดเริ่มจำลอง')+row('ดอกเบี้ยรวมประมาณ',money(t.interestTotal))+row('โปะช่วยลดดอกเบี้ยประมาณ',base.unpayable?'แผนเดิมปิดหนี้ไม่ได้':money(Math.max(0,base.interestTotal-t.interestTotal)))+details('ตารางตัดต้น–ดอก',table(['งวด','จ่าย','ดอกเบี้ย','เงินต้น','คงเหลือ'],t.rows.map(x=>[x.month,money(x.payment),money(x.interest),money(x.principal),money(x.balance)])))+'<p class="help">สมมติดอกเบี้ยรายเดือน = อัตราต่อปี ÷ 12 จ่ายปลายเดือน ไม่รวมค่าปรับและดอกเบี้ยรายวัน</p>';}
function incomeSummary(id){if(Object.entries(meta(state).unknown).some(([k,v])=>v&&k.startsWith('incomes.'+id+'.')&&!/\.(gross|withheld|costs|rate)$/.test(k)))return '<p class="callout warn">รายรับรายการนี้ยังขาดข้อมูล จึงยังไม่แสดงเงินสุทธิ</p>';const r=state.incomes.find(x=>x.id===id);if(!r)return '';const b=incomeBreakdown(state,r);return `<div class="inline-note">${row('เงินสะสมหักผ่านเงินเดือนที่เชื่อม / งวด',money(b.pvd))}${row(r.amountMode==='gross'?'รวมรายการหัก / งวด':'รายการหักที่บันทึกไว้ (ไม่หักซ้ำ)',money(b.deductions))}${row('เงินรับเข้าบัญชี / งวด',`<span class="${b.net<0?'negative':'green'}">${money(b.net)} บาท</span>`)}</div>`}
function pvdLinked(){const ps=state.portfolios.filter(p=>p.type==='PVD');return ps.length?table(['PVD','มูลค่าปัจจุบัน','เงินสะสม / เดือน','นายจ้าง / เดือน','ยอดภาษีทั้งปี'],ps.map(p=>[esc(p.name),money(p.value),money(p.monthly),money(p.employer),money(portfolioTax(p,state))+(p.taxAuto?' (ประมาณการ)':'')])):empty('ยังไม่พบ PVD','เพิ่มจากหน้าข้อมูลการเงินได้ หากไม่มีให้ข้าม')}
function socialSummary(){return row('สถานะประกันสังคม',state.retirement.socialScheme==='none'?'ไม่มี (หากยังไม่ทราบ ให้บันทึกในหมายเหตุ)':'มาตรา '+esc(state.retirement.socialScheme))+row('ส่งเงินสมทบสะสมแล้ว',money(state.retirement.socialMonths)+' เดือน')+row('หักผ่านรายรับ (เฉลี่ย / เดือน)',money(sum(state.incomes,r=>n(r.socialDeduct)*incomeMonths(r))/12))+row('จ่ายเองนอกสลิป / เดือน',money(state.retirement.socialOwnMonthly))+row('ยอดเชื่อมภาษีทั้งปี'+(state.tax.socialAuto?' (ประมาณการ)':' (ตามหลักฐาน)'),money(socialAnnual(state)))}
function originalUpdate(){const cf=cashflow(state),gs=goalResults(state),r=retirementResult(state),t=taxResult(state),pr=protectionResult(state);const ws=warnings(state);$('#alerts').innerHTML=ws.length?`<div class="callout warn"><b>ยังคำนวณต่อได้ แต่มีข้อมูลที่ควรตรวจ</b><ul>${ws.map(w=>`<li>${esc(w)}</li>`).join('')}</ul></div>`:'';for(const el of document.querySelectorAll('[data-result]')){const output={
 'pvd-linked':()=>pvdLinked(),'social-finance':()=>socialSummary(),'social-retirement':()=>socialSummary(),'finance-results':()=>financeResults(cf),'protection-results':()=>protectionResults(pr,cf),'goals-results':()=>goalsResults(cf,gs),'retirement-results':()=>retirementResults(r),'tax-results':()=>taxResults(t),'tax-linked':()=>taxLinked(t),'tax-home':()=>row('ดอกเบี้ยบ้านจากหน้าหนี้สิน',money(sum(state.debts,d=>n(d.homeInterest)))),'report-results':()=>reportResults(cf,gs,r,t,pr),
 'retirement-linked':()=>{const ps=state.portfolios.filter(p=>p.purpose==='retirement'),as=state.assets.filter(a=>a.kind==='cash'&&a.purpose==='retirement');return ps.length+as.length?table(['เงินเก็บเพื่อเกษียณ','มูลค่าปัจจุบัน','สมทบรวม / เดือน'],[...ps.map(p=>[esc(p.name)+' · '+portfolioTypes[p.type],money(p.value),money(p.monthly+p.employer)]),...as.map(a=>[esc(a.name),money(a.value),'—'])]):empty('ยังไม่มีเงินที่จัดสรรเพื่อเกษียณ','เลือก “เพื่อเกษียณ” ในพอร์ต หรือเงินฝากหน้าแรก')},
 'annuity-linked':()=>{const ps=state.policies.filter(p=>p.type==='annuity'&&p.insured==='self'&&active(p,state));return ps.length?table(['กรมธรรม์','รับประกัน / ปี','ช่วงอายุ'],ps.map(p=>[esc(p.company)+' '+esc(p.name),money(p.annuity),p.annuityStart+'–'+p.annuityEnd])):empty('ยังไม่มีประกันบำนาญที่เชื่อมมา','เพิ่มกรมธรรม์ประเภทบำนาญในหน้าความคุ้มครอง')}};el.innerHTML=el.id.startsWith('debt-')?debtSummary(el.id.slice(5)):el.id.startsWith('tax-income-')?taxIncomeSummary(el.id.slice(11)):el.id.startsWith('income-')?incomeSummary(el.id.slice(7)):output[el.id]?.()||''}
 for(const el of document.querySelectorAll('[data-goal-result]')){const g=gs.find(g=>g.id===el.dataset.goalResult);if(!g)continue;el.innerHTML=g.invalid?'<div class="callout error">ระบุระยะเวลามากกว่า 0 ปีเพื่อคำนวณ</div>':`<span class="badge">${g.term} · ${g.years} ปี</span>${row('เงินต้นที่เชื่อมจากสินทรัพย์ / พอร์ต',money(g.capital))}${row('ควรออมทั้งหมดต่อเดือน',money(g.required))}${row('เงินออมที่จัดสรรแล้วต่อเดือน',money(g.monthlyTotal))}${row('ต้องเพิ่มอีกต่อเดือน',money(Math.max(0,g.required-g.monthlyTotal)))}${progress('เงินที่คาดว่าจะมีเทียบเป้าหมาย',g.future,g.targetValue)}${g.locked.length?'<div class="callout warn">ยังไม่รวม '+g.locked.map(p=>esc(p.name)).join(', ')+' เพราะเงินยังไม่พร้อมใช้ในวันเป้าหมาย</div>':''}`}
 for(const el of document.querySelectorAll('[data-goal-advice]')){const g=gs.find(g=>g.id===el.dataset.goalAdvice);el.innerHTML=g?advice(g,cf):''}
 for(const el of document.querySelectorAll('[data-portfolio-summary]')){const p=state.portfolios.find(p=>p.id===el.dataset.portfolioSummary);if(!p)continue;const gain=p.value-p.cost;const years=p.start?Math.max(0,(Date.parse(state.profile.asOf)-Date.parse(p.start))/(365.25*86400000)):null;el.innerHTML=row('กำไร / ขาดทุนที่ยังไม่รับรู้',`<span class="${gain<0?'negative':'green'}">${money(gain)} บาท${p.cost?' ('+(gain/p.cost*100).toFixed(1)+'%)':''}</span>`)+row('ระยะเวลาที่ลงทุน',years!==null&&Number.isFinite(years)?years.toFixed(1)+' ปี':'ยังไม่ระบุ')+'<p class="help">ผลต่างมูลค่าเทียบต้นทุนคงเหลือ ไม่ใช่ผลตอบแทนต่อปีหรือ IRR และไม่รวมเงินปันผลที่ถอนออกแล้ว</p>'}
 for(const el of document.querySelectorAll('[data-policy-summary]')){const p=state.policies.find(p=>p.id===el.dataset.policySummary);el.textContent=p?'เบี้ยเทียบรายปี '+money(premiumAnnual(p))+' บาท • '+(active(p,state)?'อยู่ในช่วงความคุ้มครองตามข้อมูล':'ไม่อยู่ในช่วงความคุ้มครองปัจจุบัน'):''}}
function render(){const openDetails=Array.from(document.querySelectorAll('#content details')).map(d=>d.open);const previousPage=page;page=pages[location.hash.slice(1)]?location.hash.slice(1):'finance';$('#nav').innerHTML=Object.entries(pages).map(([k,v])=>`<a href="#${k}" ${page===k?'class="active" aria-current="page"':''}><span>${v[0]}</span>${v[1]}<small data-page-status="${k}">${pageStatus(state,k)}</small></a>`).join('');$('#pageName').textContent=pages[page][1];$('#content').innerHTML=heading()+experiencePanel()+({finance:financePage,protection:protectionPage,goals:goalsPage,retirement:retirementPage,tax:taxPage,report:reportPage}[page])();const keys=Object.keys(pages),i=keys.indexOf(page);$('#stepNav').innerHTML=`${i?`<button data-page="${keys[i-1]}">ย้อนกลับ: ${pages[keys[i-1]][1]}</button>`:'<span></span>'}<span class="step-index">${i+1} / 6</span>${i<5?`<button class="primary" data-page="${keys[i+1]}">ถัดไป: ${pages[keys[i+1]][1]}</button>`:'<button class="primary" data-action="export">ดาวน์โหลดไฟล์สำรอง</button>'}`;if(previousPage===page)document.querySelectorAll('#content details').forEach((d,i)=>{if(i<openDetails.length)d.open=openDetails[i]});update()}
function toast(message,undo=false){$('#toast').innerHTML=esc(message)+(undo?' <button class="mini-btn" data-action="undo">เลิกทำ</button>':'')}
function remember(){undoState=structuredClone(state)}
